# PostGIS emap 뷰를 벡터 타일(MVT)로 내보내는 MapServer 설정. 레이어 이름은 뷰 이름과 같고 style-day.json의 source-layer이다
# 뷰에는 키가 없어 뷰와 같은 질의를 원본 테이블에 직접 하고 ctid(또는 gid)를 MapServer가 요구하는 고유 키 msid로 한다. msid는 타일에 넣지 않는다
# 접속 비밀번호는 컨테이너 환경 변수 PGPASSWORD로 받는다
MAP
  NAME "emap"
  EXTENT -20037508.34 -20037508.34 20037508.34 20037508.34
  SIZE 256 256
  PROJECTION "init=epsg:3857" END
  OUTPUTFORMAT
    NAME "mvt"
    DRIVER MVT
    MIMETYPE "application/vnd.mapbox-vector-tile"
    FORMATOPTION "EXTENT=4096"
    FORMATOPTION "EDGE_BUFFER=20"
  END
  WEB METADATA "wms_enable_request" "*" "wms_srs" "EPSG:3857 EPSG:900913" "wms_getmap_formatlist" "application/vnd.mapbox-vector-tile" "wms_title" "emap" END END
  LAYER
    NAME "v_buld"
    TYPE POLYGON
    STATUS ON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=postgis dbname=route user=route"
    DATA "geom from (select ctid::text as msid, nullif(buld_nm::text,'') as name, gro_flo_co::integer as floors, geom from emap.buld) as t using unique msid using srid=3857"
    PROJECTION "init=epsg:3857" END
    METADATA "wms_title" "v_buld" "gml_include_items" "all" "gml_exclude_items" "msid" "gml_types" "auto" END
    CLASS END
  END
  LAYER
    NAME "v_road"
    TYPE LINE
    STATUS ON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=postgis dbname=route user=route"
    DATA "geom from (select gid::text as msid, gid, rn as name, roa_cls_se as cls, road_bt::real as width, wdr_rd_cd as admin, geom from emap.sprd_manage) as t using unique msid using srid=3857"
    PROJECTION "init=epsg:3857" END
    METADATA "wms_title" "v_road" "gml_include_items" "all" "gml_exclude_items" "msid" "gml_types" "auto" END
    CLASS END
  END
  LAYER
    NAME "v_road_major"
    TYPE LINE
    STATUS ON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=postgis dbname=route user=route"
    DATA "geom from (select gid::text as msid, gid, rn as name, roa_cls_se as cls, road_bt::real as width, wdr_rd_cd as admin, geom from emap.sprd_manage where roa_cls_se in ('1','2')) as t using unique msid using srid=3857"
    PROJECTION "init=epsg:3857" END
    METADATA "wms_title" "v_road_major" "gml_include_items" "all" "gml_exclude_items" "msid" "gml_types" "auto" END
    CLASS END
  END
  LAYER
    NAME "v_rw"
    TYPE POLYGON
    STATUS ON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=postgis dbname=route user=route"
    DATA "geom from (select gid::text as msid, gid, geom from emap.sprd_rw) as t using unique msid using srid=3857"
    PROJECTION "init=epsg:3857" END
    METADATA "wms_title" "v_rw" "gml_include_items" "all" "gml_exclude_items" "msid" "gml_types" "auto" END
    CLASS END
  END
  LAYER
    NAME "v_sig"
