    DATA "geom from (select gid::text as msid, gid, sig_cd as code, sig_kor_nm as name, geom from emap.scco_sig) as t using unique msid using srid=3857"
    PROJECTION "init=epsg:3857" END
    METADATA "wms_title" "v_sig" "gml_include_items" "all" "gml_exclude_items" "msid" "gml_types" "auto" END
    CLASS END
  END
  LAYER
    NAME "v_emd"
