    PROJECTION "init=epsg:3857" END
    METADATA "wms_title" "v_emd" "gml_include_items" "all" "gml_exclude_items" "msid" "gml_types" "auto" END
    CLASS END
  END
  LAYER
    NAME "v_water_low"
    TYPE POLYGON
