    CLASS END
  END
  LAYER
    NAME "v_rail2"
    TYPE LINE
    STATUS ON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=postgis dbname=route user=route"
    DATA "geom from (select ctid::text as msid, rlway_nm as name, rlroad_se as cls, geom from emap.bg_rlink where rlroad_se in ('RRC001','RRC002')) as t using unique msid using srid=3857"
    PROJECTION "init=epsg:3857" END
    METADATA "wms_title" "v_rail2" "gml_include_items" "all" "gml_exclude_items" "msid" "gml_types" "auto" END
    CLASS END
