  LAYER
    NAME "v_link"
    TYPE LINE
    STATUS ON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=postgis dbname=route user=route"
    DATA "geom from (select ctid::text as msid, road_rank as rank, nullif(road_name::text,'') as name, lanes, geom from emap.bg_link) as t using unique msid using srid=3857"
    PROJECTION "init=epsg:3857" END
    METADATA "wms_title" "v_link" "gml_include_items" "all" "gml_exclude_items" "msid" "gml_types" "auto" END
