  LAYER
    NAME "v_station"
    TYPE POINT
    STATUS ON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=postgis dbname=route user=route"
    DATA "geom from (select ctid::text as msid, (case when name::text like '%역' then name::text else name::text || '역' end)::varchar as name, lines, geom from emap.bg_station) as t using unique msid using srid=3857"
    PROJECTION "init=epsg:3857" END
    METADATA "wms_title" "v_station" "gml_include_items" "all" "gml_exclude_items" "msid" "gml_types" "auto" END
