    CONNECTION "host=postgis dbname=route user=route"
    DATA "geom from (select ctid::text as msid, frtp_cd as cls, geom from emap.bg_forest where frtp_cd in ('1','2','3','4')) as t using unique msid using srid=3857"
    PROJECTION "init=epsg:3857" END
